const projetos=[{titulo:"Campanha de alimentos",descricao:"Arrecadação de alimentos para famílias da comunidade."},{titulo:"Apoio escolar",descricao:"Atividades educativas para crianças e adolescentes."},{titulo:"Ação solidária",descricao:"Distribuição de roupas e itens essenciais."}];function criarProjetos(){return projetos.map(n=>`\n        <article class="projeto">\n            <h3>${n.titulo}</h3>\n            <p>${n.descricao}</p>\n        </article>\n    `).join("")}const routes={inicio:"\n        <section>\n            <h2>Início</h2>\n            <p>Bem-vindo à ONG Esperança.</p>\n        </section>\n    ",projetos:`\n        <section>\n            <h2>Projetos</h2>\n            <p>Conheça os projetos desenvolvidos pela ONG.</p>\n            \n            <div class="lista-projetos">\n                 ${criarprojetos()}\n            </div>\n        </section>\n    `,cadastro:"\n        <section>\n            <h2>Cadastro</h2>\n            <p>Faça seu cadastro para participar da ONG.</p>\n        </section>\n    "};function renderizarPagina(n){const o=document.getElementById("conteudo");o&&(o.innerHTML=routes[n]||routes.inicio)}function navegar(n){history.pushState({rota:n},"","#"+n),renderizarPagina(n)}window.addEventListener("popstate",()=>{renderizarPagina(location.hash.replace("#","")||"inicio")}),document.addEventListener("DOMContentLoaded",()=>{renderizarPagina(location.hash.replace("#","")||"inicio")});